<?php
namespace Zig3d_Widgets;

if (!defined('ABSPATH')) {
    exit;
}

/**
 * کمکی‌های ساخت خروجی HTML.
 *
 * هر جایی که مقدارِ واردشدهٔ کاربر به مارک‌آپ تبدیل می‌شود از همین‌جا رد
 * می‌شود، تا قواعد اسکیپ در یک نقطه بماند و «این یکی را یادم رفت» ممکن نباشد.
 */
final class Markup {

    /**
     * تگ‌هایی که کاربر می‌تواند برای عنوان انتخاب کند.
     *
     * این‌ها هم فهرست کشویی کنترل را می‌سازند و هم فهرست سفیدِ اعتبارسنجی
     * هنگام رندر — یعنی مقدار دستکاری‌شده در دیتابیس هم نمی‌تواند تگ دلخواه
     * تولید کند.
     */
    public const TAGS = [
        'h1'   => 'H1',
        'h2'   => 'H2',
        'h3'   => 'H3',
        'h4'   => 'H4',
        'h5'   => 'H5',
        'h6'   => 'H6',
        'p'    => 'P',
        'div'  => 'DIV',
        'span' => 'SPAN',
    ];

    /** تگ معتبر یا پیش‌فرض */
    public static function tag($tag, string $fallback = 'div'): string {
        $tag = strtolower(trim((string) $tag));

        return isset(self::TAGS[$tag]) ? $tag : $fallback;
    }

    /**
     * تگ‌های درون‌خطی مجاز در عنوان و توضیحات.
     *
     * هدف این است که کاربر بتواند بخشی از متن را برجسته کند (‎<span>‎ با
     * کلاس، ‎<br>‎ برای شکستن خط) بدون آنکه بتواند مارک‌آپ دلخواه — از جمله
     * ‎<script>‎ یا رویدادهای درون‌خطی — تزریق کند. style عمداً مجاز نیست:
     * همه‌چیز باید از پنل استایل بیاید تا خروجی یکدست بماند.
     */
    public static function inline_html(): array {
        return [
            'span'   => ['class' => []],
            'strong' => [],
            'b'      => [],
            'em'     => [],
            'i'      => [],
            'u'      => [],
            'mark'   => ['class' => []],
            'small'  => [],
            'sub'    => [],
            'sup'    => [],
            'br'     => [],
            'bdi'    => [],
            'wbr'    => [],
        ];
    }

    /** متن با تگ‌های درون‌خطی مجاز */
    public static function text(string $value): string {
        return wp_kses($value, self::inline_html());
    }

    /**
     * آیا این رشته بعد از حذف تگ‌ها و فاصله‌ها چیزی دارد؟
     *
     * ‎'' !== $value‎ کافی نیست: کاربر خیلی وقت‌ها فیلد را با یک ‎<br>‎ یا چند
     * فاصله «خالی» می‌کند و آن‌وقت یک عنصر تهی با پدینگ و حاشیه رندر می‌شد.
     */
    /**
     * آیکون خطی، به‌صورت SVG درون‌خطی.
     *
     * چرا درون‌خطی و نه فونت آیکون یا فایل جدا: این‌ها شکل‌های ثابتی‌اند که
     * هیچ‌وقت عوض نمی‌شوند و مجموعاً چند صد بایت‌اند. یک درخواست HTTP
     * اضافه یا یک وابستگی به کتابخانهٔ آیکون، برای چند مسیرِ ‎path‎ توجیه
     * ندارد — و آیکونی که دیر می‌رسد، دکمه‌ای می‌سازد که یک لحظه خالی است.
     *
     * ‎currentColor‎ یعنی رنگش از متنِ اطرافش می‌آید، پس کنترل رنگِ پنل در
     * المنتور خودبه‌خود آیکون را هم می‌گیرد.
     *
     * ‎aria-hidden‎ چون همه تزئینی‌اند: کنارشان همیشه متن هست.
     *
     * ‎$view_box‎ اختیاری است چون همهٔ آیکون‌ها روی یک شبکهٔ ۲۴واحدی طراحی
     * نشده‌اند — ‎flame‎ که مستقیماً از فیگما آمده روی شبکهٔ ۱۴واحدی است؛
     * دادنِ مقدارِ اشتباه یعنی آیکون کوچک و کنج‌افتاده رندر شود، نه کجی در
     * خودِ ‎path‎.
     */
    public static function svg_icon(string $name, string $class = '', int $view_box = 24): string {
        $paths = [
            'filter'   => '<path d="M3 5h18M6 12h12M10 19h4"/>',
            'trash'    => '<path d="M4 7h16M9 7V5h6v2M6 7l1 13h10l1-13M10 11v6M14 11v6"/>',
            'chevron'  => '<path d="M6 9l6 6 6-6"/>',
            'arrow'    => '<path d="M19 12H5M11 18l-6-6 6-6"/>',
            'sort'     => '<path d="M4 6h16M7 12h10M10 18h4"/>',
            'phone'    => '<path d="M6 3h4l2 5-3 2a12 12 0 005 5l2-3 5 2v4a2 2 0 01-2 2A16 16 0 014 5a2 2 0 012-2z"/>',
            'close'    => '<path d="M6 6l12 12M18 6L6 18"/>',
            'search'   => '<circle cx="10.5" cy="10.5" r="6.5"/><path d="M20 20l-4.3-4.3"/>',
            // از فیگما (node 1:198)، شبکهٔ ۱۴واحدی — نگاه کنید به توضیح ‎$view_box‎ بالا
            'flame'    => '<path d="M9.3336 5.54183C8.1668 4.56956 7.38893 3.30562 7 1.75C6.02767 2.52781 5.5415 3.30562 5.5415 4.08343C5.5415 5.25015 6.4166 5.83351 6.4166 7.00022C6.4166 7.38701 6.26294 7.75796 5.98942 8.03146C5.71589 8.30496 5.34492 8.45862 4.9581 8.45862C4.57128 8.45862 4.20031 8.30496 3.92678 8.03146C3.65326 7.75796 3.4996 7.38701 3.4996 7.00022C3.12091 7.50511 2.9162 8.11919 2.9162 8.75029C2.9162 9.83331 3.34646 10.872 4.11232 11.6378C4.87818 12.4036 5.91691 12.8338 7 12.8338C8.08309 12.8338 9.12182 12.4036 9.88768 11.6378C10.6535 10.872 11.0838 9.83331 11.0838 8.75029C11.0838 7.58358 10.5004 6.51409 9.3336 5.54183Z"/>',
        ];

        if (!isset($paths[$name])) {
            return '';
        }

        return sprintf(
            '<svg class="%1$s" viewBox="0 0 %2$d %2$d" fill="none" stroke="currentColor" stroke-width="1.8"'
                . ' stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">%3$s</svg>',
            esc_attr(trim('zig-icon-line ' . $class)),
            $view_box,
            $paths[$name]
        );
    }

    /**
     * آیکونِ پرشده (filled path)، برایِ نمادهایی که در فیگما با ‎fill‎
     * طراحی شده‌اند نه ‎stroke‎ — برخلافِ ‎svg_icon()‎ بالا که همه را رویِ یک
     * شبکهٔ مربعیِ stroke-based می‌کشد. هر آیکون اینجا ‎viewBox‎ و نسبتِ
     * ابعادِ خودش را دارد (مثلاً نوارِ موبایلِ آرشیوِ محصولات: قیفِ فیلتر
     * ۱۵×۱۴، فهرستِ ترتیب ۲۱×۲۰ — مستقیم از فیگما) پس اندازه با کلاسِ CSS
     * تنظیم می‌شود، نه با ‎$view_box‎ی ثابت.
     *
     * رنگِ اصلیِ فیگما (‎#17171B‎ با ‎fill-opacity: 0.9‎) همان
     * ‎rgba(23, 23, 27, 0.9)‎ است؛ همان رنگ را مستقیم به ‎currentColor‎
     * می‌دهیم (نه ‎fill‎ی ثابت + ‎fill-opacity‎ی جدا) تا یک کنترلِ رنگِ
     * واحد در استایل، هم رنگ و هم شفافیت را با هم عوض کند.
